export interface Phase2ServiceActor {userId:string;workspaceId:string}
export interface Phase2RuntimeConfig {publicBaseUrl:string;unsubscribeSecret:string;trackingSecret:string;maxMessageBytes:number;providerReady?:boolean;requireWorkspaceConfigurationSet?:boolean;testRecipientAllowlist?:string[];unsubscribePublicBaseOnly?:boolean}
